const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Halemaumau Crater location
  const crater = ee.Geometry.Point([-155.2834, 19.4069]);
  const craterBuffer = crater.buffer(500); // 500m buffer around crater center

  // July 20, 2025, 10:44 am HST = 20:44 UTC on July 20, 2025
  // Check a window around this time
  const targetDate = '2025-07-20';
  const startDate = '2025-07-19';
  const endDate = '2025-07-21';

  console.log('Searching for volcanic eruption evidence on July 20, 2025...');

  // Try multiple thermal data sources

  // 1. MODIS Terra (morning pass ~10:30 am local)
  const modis = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(crater);

  const modisCount = modis.size().getInfo();
  console.log('MODIS Terra images found:', modisCount);

  // 2. Landsat 8/9 thermal
  const landsat9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(crater);

  const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(crater);

  const l9Count = landsat9.size().getInfo();
  const l8Count = landsat8.size().getInfo();
  console.log('Landsat 9 images:', l9Count, '| Landsat 8 images:', l8Count);

  // 3. Sentinel-2 for visual confirmation
  const s2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(crater);

  const s2Count = s2.size().getInfo();
  console.log('Sentinel-2 images:', s2Count);

  // Check if any data exists
  if (modisCount === 0 && l9Count === 0 && l8Count === 0 && s2Count === 0) {
    console.log('No satellite data available for July 20, 2025.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Analyze MODIS thermal data if available
  if (modisCount > 0) {
    const modisImg = modis.first();
    const lstDay = modisImg.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Convert to Celsius

    const thermalStats = lstDay.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.max(),
        sharedInputs: true
      }).combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: craterBuffer,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const meanTemp = thermalStats['LST_Day_1km_mean'];
    const maxTemp = thermalStats['LST_Day_1km_max'];
    const pixelCount = thermalStats['LST_Day_1km_count'];

    console.log('Crater thermal stats (MODIS):');
    console.log('  Mean temp:', meanTemp ? meanTemp.toFixed(2) : 'null', 'C');
    console.log('  Max temp:', maxTemp ? maxTemp.toFixed(2) : 'null', 'C');
    console.log('  Valid pixels:', pixelCount);

    if (pixelCount === 0) {
      console.log('No valid thermal pixels.');
      console.log('<answer>C2</answer>');
      return;
    }

    if (meanTemp === null || meanTemp === undefined || maxTemp === null) {
      console.log('Thermal calculation failed.');
      console.log('<answer>C3</answer>');
      return;
    }

    // Volcanic eruption typically shows temperatures > 100C in thermal imagery
    // Active lava can be 700-1200C but satellite thermal bands saturate/average lower
    if (maxTemp > 80) {
      console.log('Significant thermal anomaly detected - consistent with eruption.');
      console.log('<answer>A</answer>');
      return;
    }
  }

  // Check Landsat thermal if available
  if (l9Count > 0 || l8Count > 0) {
    const landsatCol = l9Count > 0 ? landsat9 : landsat8;
    const landsatImg = landsatCol.first();
    const thermalBand = landsatImg.select('ST_B10').multiply(0.00341802).add(149.0).subtract(273.15);

    const thermalStats = thermalBand.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.max(),
        sharedInputs: true
      }).combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: craterBuffer,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const meanTemp = thermalStats['ST_B10_mean'];
    const maxTemp = thermalStats['ST_B10_max'];
    const pixelCount = thermalStats['ST_B10_count'];

    console.log('Crater thermal stats (Landsat):');
    console.log('  Mean temp:', meanTemp ? meanTemp.toFixed(2) : 'null', 'C');
    console.log('  Max temp:', maxTemp ? maxTemp.toFixed(2) : 'null', 'C');
    console.log('  Valid pixels:', pixelCount);

    if (pixelCount === 0) {
      console.log('No valid thermal pixels.');
      console.log('<answer>C2</answer>');
      return;
    }

    if (meanTemp === null || maxTemp === null) {
      console.log('Thermal calculation failed.');
      console.log('<answer>C3</answer>');
      return;
    }

    if (maxTemp > 80) {
      console.log('Significant thermal anomaly detected - consistent with eruption.');
      console.log('<answer>A</answer>');
      return;
    }
  }

  console.log('No significant thermal anomaly detected on July 20, 2025.');
  console.log('<answer>B</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
